output.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?olderFilm WHERE {
  {
    dbr:Four_Days_in_November dbo:director ?dirA .
    ?dirA dbo:birthDate ?bA .
    dbr:The_Romance_of_Tarzan dbo:director ?dirB .
    ?dirB dbo:birthDate ?bB .
    FILTER(?bB < ?bA)
    BIND(dbr:The_Romance_of_Tarzan AS ?olderFilm)
  } UNION {
    dbr:Four_Days_in_November dbo:director ?dirA .
    ?dirA dbo:birthDate ?bA .
    dbr:The_Romance_of_Tarzan dbo:director ?dirB .
    ?dirB dbo:birthDate ?bB .
    FILTER(?bA < ?bB)
    BIND(dbr:Four_Days_in_November AS ?olderFilm)
  }
}
LIMIT 10
